<script>
const cap=document.getElementById('cap'),left=document.querySelector('.left'),svg=document.getElementById('mascot'),capTxt=document.getElementById('capTxt');
const eyes=[...svg.querySelectorAll('.eye')].map(g=>({p:g.querySelector('.pupil'),x:+g.dataset.cx,y:+g.dataset.cy,m:+g.dataset.m}));
let target=null;
const toSvg=(cx,cy)=>{const pt=svg.createSVGPoint();pt.x=cx;pt.y=cy;return pt.matrixTransform(svg.getScreenCTM().inverse())};
function look(){
  const sad=svg.classList.contains('sad');
  eyes.forEach(e=>{
    let dx=0,dy=0;
    if(sad){dy=e.m*.8}
    else if(target){const vx=target.x-e.x,vy=target.y-e.y,d=Math.hypot(vx,vy)||1,k=Math.min(1,d/90);dx=vx/d*e.m*k;dy=vy/d*e.m*k}
    e.p.style.transform=`translate(${dx}px,${dy}px)`;
  });
}
const aim=(x,y)=>{target=toSvg(x,y);look()};
addEventListener('mousemove',e=>aim(e.clientX,e.clientY));
addEventListener('touchmove',e=>{const t=e.touches[0];aim(t.clientX,t.clientY)},{passive:true});
document.querySelectorAll('input').forEach(i=>i.addEventListener('focus',()=>{const r=i.getBoundingClientRect();aim(r.left+r.width/2,r.top+r.height/2)}));

function setSad(on,msg){
  svg.classList.remove('sad');void svg.getBoundingClientRect(); // restart animasi
  if(on)svg.classList.add('sad');
  left.classList.toggle('sadbg',on);
  cap.classList.remove('sad');cap.style.animation='none';void cap.offsetWidth;cap.style.animation='';cap.classList.toggle('sad',on);
  capTxt.innerHTML=on?'Hmm, '+(msg||'ada yang salah')+'<small>Coba periksa lagi ya.</small>':'Yuk masuk, kami sudah menunggumu!';
  look();
}
if(svg.classList.contains('sad'))setSad(true,'<?= $error ? 'username/email atau kata sandi salah' : '' ?>'.toLowerCase());

// kembali ceria saat user mengetik ulang
document.querySelectorAll('input').forEach(i=>i.addEventListener('input',()=>{
  if(svg.classList.contains('sad')){setSad(false);document.querySelectorAll('.field').forEach(f=>f.classList.remove('err'));document.getElementById('alert').classList.remove('on')}
}));

// validasi sisi klien
document.getElementById('form').addEventListener('submit',e=>{
  const id=document.getElementById('identity').value.trim(),pw=document.getElementById('pw').value;
  if(!id||!pw){
    e.preventDefault();
    const a=document.getElementById('alert');a.textContent='Username/email dan kata sandi wajib diisi.';a.classList.remove('on');void a.offsetWidth;a.classList.add('on');
    setSad(true,'kolomnya belum lengkap');
  }
});

// lihat/sembunyikan sandi
const tog=document.getElementById('tog'),pw=document.getElementById('pw');
tog.onclick=()=>{const s=pw.type==='password';pw.type=s?'text':'password';tog.textContent=s?'Sembunyi':'Lihat'};
look();
</script>
